"""Independently designed raw-field, chronology, permutation and provenance probes."""
from copy import deepcopy
from dataclasses import asdict
from datetime import date, datetime, timedelta, timezone
import hashlib
import importlib.util
from itertools import permutations
import json
from pathlib import Path
import sys

import pytest

from toto_ai.external_odds.goal_api import GoalAPIClient, GoalAPIError, _parse_event, _schedule_semantic_hash
from toto_ai.external_odds.schedule_source_collector import _collect_goal_api_candidates
from tests.test_goal_api_provider import FakeResponse, FakeSession, _fixture, _now
from tests.test_goal_api_schedule_collection import _queue

FROZEN = json.loads((Path(__file__).parent / 'fixtures/goal_pagination_duplicate.json').read_text())
BASE = FROZEN['observations'][0]['raw_event']
UTC = timezone.utc

def h(obj):
    return hashlib.sha256(json.dumps(obj, ensure_ascii=True, sort_keys=True, separators=(',', ':')).encode()).hexdigest()

def run(tmp, rows, times=None, requested=None):
    bodies = [{'success': True, 'data': [row], 'pagination': {'hasMore': i + 1 < len(rows), 'nextOffset': i + 1}} for i, row in enumerate(rows)]
    clock = iter(times or [_now()] * len(rows))
    client = GoalAPIClient('independent-synthetic-key', session=FakeSession([FakeResponse(b) for b in bodies]), snapshot_dir=tmp, now=lambda: next(clock), max_retries=0)
    result = client.fetch_schedule(requested or (date(2026, 8, 26),))
    for body, evidence in zip(bodies, client.request_evidence, strict=True):
        content = evidence.snapshot_path.read_bytes()
        doc = json.loads(content)
        assert hashlib.sha256(content).hexdigest() == evidence.snapshot_sha256
        assert doc['payload'] == body and h(body) == evidence.response_hash == doc['response_hash']
        assert doc['request_fingerprint'] == evidence.request_fingerprint
        assert doc['endpoint'] == evidence.endpoint
        assert datetime.fromisoformat(doc['fetched_at'].replace('Z', '+00:00')) == evidence.fetched_at
    for event in result:
        matches = [e for e in client.request_evidence if (e.fetched_at, e.endpoint, e.request_fingerprint) == (event.captured_at, event.source_endpoint, event.request_fingerprint)]
        assert len(matches) == 1
        raw = json.loads(matches[0].snapshot_path.read_text())['payload']['data'][0]
        expected = _parse_event(raw, fetched_at=event.captured_at, endpoint=event.source_endpoint, request_fingerprint=event.request_fingerprint)
        assert event == expected and event.payload_hash == h(raw)
        provider = event.as_provider_event()
        assert provider.payload_hash == event.payload_hash and provider.fetched_at == event.captured_at
    return result, client

@pytest.mark.parametrize('field', sorted(set(BASE) - {'updatedAt'}))
def test_every_frozen_raw_field_remains_semantic(field):
    changed = deepcopy(BASE)
    changed[field] = {'independent_change': BASE[field]}
    assert _schedule_semantic_hash(changed) != _schedule_semantic_hash(BASE)
    del changed[field]
    assert _schedule_semantic_hash(changed) != _schedule_semantic_hash(BASE)

@pytest.mark.parametrize('field', sorted(set(BASE) - {'id', 'updatedAt'}))
@pytest.mark.parametrize('reverse', [False, True])
def test_each_frozen_field_conflict_rejects_at_public_fetch(tmp_path, field, reverse):
    changed = deepcopy(BASE)
    old = changed[field]
    changed[field] = old + ' independent change' if isinstance(old, str) else {'independent_change': old}
    rows = [BASE, changed][::-1] if reverse else [BASE, changed]
    with pytest.raises(GoalAPIError):
        run(tmp_path, rows, requested=(date(2026, 9, 5),))

@pytest.mark.parametrize('mutation', ['nested_updatedAt', 'createdAt', 'absent_null', 'list_order', 'bool_int', 'string_int', 'raw_status_alias', 'same_normalized_id'])
@pytest.mark.parametrize('reverse', [False, True])
def test_sensitive_non_metadata_differences(tmp_path, mutation, reverse):
    first = _fixture()
    second = deepcopy(first)
    if mutation == 'nested_updatedAt':
        first['extra'] = {'updatedAt': 'a'}
        second['extra'] = {'updatedAt': 'b'}
    elif mutation == 'createdAt':
        first['createdAt'] = 'a'
        second['createdAt'] = 'b'
    elif mutation == 'absent_null':
        second['unknown'] = None
    elif mutation == 'list_order':
        first['unknown'] = [1, 2]
        second['unknown'] = [2, 1]
    elif mutation == 'bool_int':
        first['unknown'] = True
        second['unknown'] = 1
    elif mutation == 'string_int':
        first['unknown'] = '1'
        second['unknown'] = 1
    elif mutation == 'raw_status_alias':
        second['matchStatus'] = 'NS'
    else:
        second['id'] = ' 7001 '
    with pytest.raises(GoalAPIError, match='duplicate event identity conflicts'):
        run(tmp_path, [second, first] if reverse else [first, second])

@pytest.mark.parametrize('value', [None, '', 'new timestamp', 42, {'nested': ['bookkeeping']}])
def test_only_top_level_updated_at_is_ignored_including_absence(tmp_path, value):
    first = _fixture()
    second = first | {'updatedAt': value}
    events, _ = run(tmp_path, [first, second])
    assert len(events) == 1 and events[0].eligible

def test_nested_object_key_order_not_a_conflict(tmp_path):
    first = _fixture() | {'unknown': {'a': 1, 'b': {'x': 1, 'y': 2}}}
    second = dict(reversed(list(first.items())))
    second['unknown'] = {'b': {'y': 2, 'x': 1}, 'a': 1}
    events, _ = run(tmp_path, [first, second])
    assert len(events) == 1

@pytest.mark.parametrize('tie', [False, True])
def test_six_fixed_observation_permutations_select_same_real_row(tmp_path, tie):
    rows = [_fixture() | {'updatedAt': x} for x in ('provider-newest', 'provider-oldest', 'provider-middle')]
    times = [_now()] * 3 if tie else [_now() + timedelta(seconds=x) for x in (2, 0, 1)]
    selected = []
    for i, perm in enumerate(permutations(range(3))):
        (event,), _ = run(tmp_path / str(i), [rows[x] for x in perm], [times[x] for x in perm])
        assert event.captured_at == max(times)
        selected.append((event.payload_hash, event.captured_at, event.status, event.eligible))
    assert len(set(selected)) == 1
    expected = max(range(3), key=lambda x: (times[x], h(rows[x])))
    assert selected[0][0] == h(rows[expected])

def test_identical_raw_tied_time_fingerprint_tie_break(tmp_path):
    (event,), client = run(tmp_path, [_fixture()] * 3)
    assert event.request_fingerprint == max(e.request_fingerprint for e in client.request_evidence)

@pytest.mark.parametrize('reverse', [False, True])
def test_frozen_records_with_original_captures(tmp_path, reverse):
    observations = FROZEN['observations'][::-1] if reverse else FROZEN['observations']
    rows = [o['raw_event'] for o in observations]
    times = [datetime.fromisoformat(o['captured_at'].replace('Z', '+00:00')) for o in observations]
    (event,), _ = run(tmp_path, rows, times, (date(2026, 9, 5),))
    assert event.payload_hash == max(h(r) for r in rows)
    assert not event.eligible and event.status == 'finished'

@pytest.mark.parametrize('reverse', [False, True])
def test_exact_kickoff_and_utc_offset_do_not_preserve_old_eligibility(tmp_path, reverse):
    kickoff = datetime(2026, 8, 26, 19, tzinfo=UTC)
    rows = [_fixture() | {'updatedAt': 'one'}, _fixture() | {'updatedAt': 'two'}]
    times = [kickoff - timedelta(microseconds=1), kickoff.astimezone(timezone(timedelta(hours=3)))]
    (event,), _ = run(tmp_path, rows[::-1] if reverse else rows, times[::-1] if reverse else times)
    assert not event.eligible and event.captured_at == kickoff

def test_conflict_after_equivalent_chain_is_not_hidden(tmp_path):
    rows = [_fixture() | {'updatedAt': x} for x in ('one', 'two')]
    rows.append(_fixture() | {'homeTeamScore': '1'})
    for i, perm in enumerate(permutations(rows)):
        with pytest.raises(GoalAPIError, match='duplicate event identity conflicts'):
            run(tmp_path / str(i), perm)

def test_mixed_identity_results_sorted_not_discovery_order(tmp_path):
    first = _fixture(event_id=7001)
    second = _fixture(event_id=7002)
    results = []
    for i, rows in enumerate(([second, first, first], [first, first, second])):
        events, _ = run(tmp_path / str(i), rows)
        results.append([(e.provider_event_id, e.status, e.eligible, e.payload_hash) for e in events])
    assert results[0] == results[1]

def test_collector_real_conflict_has_no_partial_candidates(tmp_path):
    class Session:
        def get(self, url, *, params, headers, timeout):
            data = []
            more = False
            if url.endswith('2026-08-26'):
                later = params['offset'] != '0'
                data = [_fixture() | ({'homeTeamScore': '1'} if later else {})]
                more = not later
            return FakeResponse({'success': True, 'data': data, 'pagination': {'hasMore': more, 'nextOffset': 1}})
    client = GoalAPIClient('independent-synthetic-key', session=Session(), snapshot_dir=tmp_path / 'snapshots', now=_now)
    records, status = _collect_goal_api_candidates(json.loads(_queue(tmp_path).read_text()), output=tmp_path / 'out', observed=_now(), deadline=datetime(2026, 8, 26, 18, 45, tzinfo=UTC), ledger=None, config=None, client=client, team_aliases={'Викинг': 'Viking', 'Динамо Загреб': 'Dinamo Zagreb'})
    assert status['status'] == 'source_failed' and status['candidate_count'] == 0
    assert all(r['status'] == 'source_failed' and r['ledger_eligible'] is False for r in records)

@pytest.mark.parametrize('status', ['Not Started', 'Scheduled', 'UNKNOWN', 'FINISHED', 'POSTPONED', 'CANCELLED'])
@pytest.mark.parametrize('after_kickoff', [False, True])
def test_single_observation_matches_exact_unpatched_behavior(tmp_path, status, after_kickoff):
    path = Path('/Users/turshevr/toto-ai/src/toto_ai/external_odds/goal_api.py')
    assert hashlib.sha256(path.read_bytes()).hexdigest() == '9664414b31134122474a7ffc33f15be24a58111f1a7ec42f915c3423db82dab8'
    name = 'toto_ai.external_odds.goal_api_review_baseline'
    if name not in sys.modules:
        spec = importlib.util.spec_from_file_location(name, path)
        baseline = importlib.util.module_from_spec(spec)
        sys.modules[name] = baseline
        spec.loader.exec_module(baseline)
    baseline = sys.modules[name]
    clock = datetime(2026, 8, 26, 20, tzinfo=UTC) if after_kickoff else _now()
    raw = _fixture() | {'matchStatus': status, 'updatedAt': 'opaque metadata', 'extra': {'updatedAt': 'nested', 'unicode': 'Пример', 'scores': [None, '0', 0, False]}}
    body = {'success': True, 'data': [raw], 'pagination': {'hasMore': False}}
    outputs = []
    for label, cls in [('before', baseline.GoalAPIClient), ('after', GoalAPIClient)]:
        client = cls('independent-synthetic-key', session=FakeSession([FakeResponse(deepcopy(body))]), snapshot_dir=tmp_path / label, now=lambda: clock)
        events = client.fetch_schedule((date(2026, 8, 26),))
        outputs.append(([asdict(e) for e in events], client.request_evidence[0].snapshot_path.read_bytes(), [asdict(d) for d in client.request_diagnostics]))
    assert outputs[0] == outputs[1]

def test_date_order_and_equal_capture_endpoint_tie_break(tmp_path):
    class Session:
        def get(self, url, *, params, headers, timeout):
            return FakeResponse({'success': True, 'data': [_fixture()], 'pagination': {'hasMore': False}})
    outputs = []
    dates = (date(2026, 8, 25), date(2026, 8, 26))
    for i, order in enumerate((dates, dates[::-1])):
        client = GoalAPIClient('independent-synthetic-key', session=Session(), snapshot_dir=tmp_path / str(i), now=_now)
        (event,) = client.fetch_schedule(order)
        outputs.append(event)
        assert event.source_endpoint.endswith('2026-08-26')
        assert event.request_fingerprint == client.request_evidence[1].request_fingerprint
        assert event.captured_at == client.request_evidence[1].fetched_at
        assert h(json.loads(client.request_evidence[1].snapshot_path.read_text())['payload']['data'][0]) == event.payload_hash
    assert outputs[0] == outputs[1]
